insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('3f02ba72-4a56-4671-9b12-aadfb4763174', 'situacion', 'BUGS BUNNY S2 · Pregunta 41', 'ctx-sit', '<p>Una empresa ofrece un salario básico de $950.000 más $75.000 por cada año de experiencia del aspirante.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e6e0f0ea-cfef-42be-b35b-cce519fe3661', 'situacion', 'BUGS BUNNY S2 · Pregunta 42', 'ctx-sit', '<p>Para hallar la moda se cuenta cuántas veces aparece cada número y se elige el de mayor frecuencia.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('fe7c4f2a-3105-4c26-8b8c-0d79877a7faf', 'situacion', 'BUGS BUNNY S2 · Pregunta 43', 'ctx-sit', '<p>Una empresa vende regularmente 40 piezas a $30 cada una. Cuando vende más de 40 y menos de 80, calcula: ingreso adicional = (piezas − 40)×30; después divide ese ingreso entre 40×30.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('cb43a7fe-ea15-492d-870a-7fb97eefdde0', 'situacion', 'BUGS BUNNY S2 · Pregunta 44', 'ctx-sit', '<p>Una tienda ofrece un descuento del 20 % en todas sus prendas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('ec719f23-9e5f-4adb-8ad3-ee6216de6eb5', 'situacion', 'BUGS BUNNY S2 · Pregunta 45', 'ctx-sit', '<p>Después del lanzamiento de un producto en agosto, el gerente afirma que los ingresos aumentaron de manera creciente en los tres meses siguientes.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q45-ingresos.webp" alt="Ingresos de agosto, septiembre, octubre y noviembre; octubre tiene una barra más baja que septiembre." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('96afdd48-7b40-4e2f-a5fe-e40182564b5f', 'situacion', 'BUGS BUNNY S2 · Pregunta 46', 'ctx-sit', '<p>Cinco vacas se pesan por la mañana. Cada una consume cerca de 10 kg de comida durante el día y 10 litros de agua principalmente de noche. El productor escoge un camión liviano, pero al cargarlo por la tarde supera su capacidad.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q46-tablas.webp" alt="Pesos 652, 690, 774, 676 y 703 kg: total 3.495. Capacidades de camiones: ligero 2.500, liviano 3.500, mediano 4.500 y pesado 7.500 kg." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8b5791a9-06c5-4700-869c-624a8f473161', 'situacion', 'BUGS BUNNY S2 · Pregunta 47', 'ctx-sit', '<p>A la carta: se ordena un plato de precio establecido y al pagar se agrega el 10 % de servicio. Autoservicio: se toman y pesan alimentos, y no se cobra servicio. La línea continua representa la carta y la punteada el autoservicio.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('86fe941d-1646-4808-9dde-4d309dd98362', 'situacion', 'BUGS BUNNY S2 · Pregunta 48', 'ctx-sit', '<p>Se lanzan dos dados equilibrados de seis caras. Se llama par a que ambos muestren el mismo número. Un estudiante cree que es más probable sumar once que obtener un par.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0af17789-ac78-464d-9e97-e607786560cf', 'situacion', 'BUGS BUNNY S2 · Pregunta 49', 'ctx-sit', '<p>Una agencia calcula el pasaje con T = (1/e + m + s²)k. e es el número de escalas, m el de maletas, s los días de viaje y k un valor fijo por aerolínea. Isabella lleva cinco maletas, hace una escala y permanece dos semanas.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('5d9c73b3-2df2-497d-8897-355a9b41d412', 'situacion', 'BUGS BUNNY S2 · Pregunta 50', 'ctx-sit', '<p>Alberto ahorra el 2 % de su salario mensual de $800.000: $16.000. Estefanía gana $900.000 y desea ahorrar el 3 % cada mes.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('af152450-0337-4990-aece-bccb61c065ea', 'situacion', 'BUGS BUNNY S2 · Pregunta 51', 'ctx-sit', '<p>Marlon da cinco vueltas a un parque por la mañana y dos por la tarde. Recorre 1.400 metros en total. El perímetro del parque es n metros.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0155e004-28e3-4904-bfe3-e8b2ff989c0e', 'situacion', 'BUGS BUNNY S2 · Pregunta 52', 'ctx-sit', '<p>Una flecha está en el primer cuadrante y apunta al norte. Se refleja respecto al eje y y después se rota 180° alrededor del origen.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q52-flecha.webp" alt="Flecha orientada hacia arriba en el primer cuadrante; ejes cartesianos y rosa de los vientos." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e3b383cf-55e0-42d2-8c6e-c5682a973d29', 'situacion', 'BUGS BUNNY S2 · Pregunta 53', 'ctx-sit', '<p>La gráfica muestra la altura de un esquiador mientras desciende por una montaña.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q53-altura.webp" alt="Recta desde una altura de 14 m a los 0 s hasta 0 m a los 28 s." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('0b8d2006-2ecb-43aa-9ef9-312476a186d4', 'situacion', 'BUGS BUNNY S2 · Pregunta 54', 'ctx-sit', '<p>Roberto mide 140 cm. La tabla muestra la estatura mínima y el tiempo de fila de cinco atracciones.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q54-tabla.webp" alt="P: 130 cm, 10 min; Q: 135 cm, 11 min; R: 160 cm, 15 min; S: 150 cm, 8 min; T: 120 cm, 9 min." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('d7e2d01f-84e7-4396-976a-65995d1da5d4', 'situacion', 'BUGS BUNNY S2 · Pregunta 55', 'ctx-sit', '<p>En una repisa caben cuatro trofeos. Para contar maneras de organizarlos, Camila cuenta sus n trofeos y calcula las permutaciones de n elementos tomados de cuatro en cuatro.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7a4859d5-a30b-4450-b272-b286690a2baf', 'situacion', 'BUGS BUNNY S2 · Pregunta 56', 'ctx-sit', '<p>El diagrama distribuye a 160 personas por los medios de transporte que usan para llegar al trabajo.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q56-venn.webp" alt="Solo carro 35; solo bicicleta 50; solo transporte público 10; carro y bicicleta 20; carro y público 15; bicicleta y público 25; los tres 5." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e57b72d4-1bd8-4444-b461-d2b4959f7229', 'situacion', 'BUGS BUNNY S2 · Pregunta 57', 'ctx-sit', '<p>Una fachada mide 10 m de ancho y 15 m de alto. Cada ventana tiene un área de 1 m² y la puerta de acceso, de 2 m². Se pintará la fachada excluyendo ventanas y puerta.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q57-edificio.webp" alt="Fachada rectangular con diez ventanas, dispuestas en cinco filas de dos, y una puerta." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('633b6885-0298-4f2f-94e5-1bc66c120e4c', 'situacion', 'BUGS BUNNY S2 · Pregunta 58', 'ctx-sit', '<p>Para elegir la carrera más económica entre seis universidades se propone: 1. Registrar el costo total en cada universidad. 2. Ordenar los seis costos de menor a mayor. 3. Elegir el primero. 4. Descartar los cinco últimos.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e1f29891-26a3-40f4-bedc-3510861d165a', 'situacion', 'BUGS BUNNY S2 · Pregunta 59', 'ctx-sit', '<p>Seis habitantes reparten el aseo de la entrada de un edificio. Se limpia dos veces al día, de lunes a sábado. El procedimiento usa 26 días por mes y 12 meses por año, divide los días entre seis habitantes y multiplica por dos limpiezas diarias.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7450931a-07ee-4941-a68b-31d5469f9b60', 'situacion', 'BUGS BUNNY S2 · Pregunta 60', 'ctx-sit', '<p>En coordenadas polares, r indica la distancia a la torre y θ el ángulo desde el eje polar.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q60-polar.webp" alt="Aviones V(30 km,30°), W(20 km,90°), X(60 km,180°) y Y(40 km,60°)." loading="lazy"></figure>');

