insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8bea40ed-2541-48da-a7ad-e205a48459de', 2, 'Si x es la experiencia en años, el salario es 950.000 + 75.000x. El básico se recibe una sola vez, independientemente de la experiencia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
