insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6cc47324-be52-4924-893b-a0512fee68ef', 1, 'En {2, 3, 4, 5, 5, 6}, solo el 5 se repite dos veces; los demás aparecen una vez. Los otros conjuntos empatan en su frecuencia máxima.');

