insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '70208ada-7454-41fa-8fba-bc34dc26d5ba', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  '96afdd48-7b40-4e2f-a5fe-e40182564b5f', 'Interpretación de datos',
  '¿Cómo puede mejorar la estimación del peso para escoger el camión?',
  array['Pesar una vez a última hora de la noche y sumar los pesos.', 'Pesar a cada vaca en varios momentos del día y sumar sus pesos máximos.', 'Pesar con una balanza digital más precisa y sumar los pesos.', 'Pesar varias veces a primera hora de la mañana y sumar los máximos.'],
  'Elige mediciones que cubran la variación relevante para la decisión.', 'publicada', 'modelo', '3e3b1a2da0e797ac918e16d8cd33f948', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('70208ada-7454-41fa-8fba-bc34dc26d5ba', 1, 'La alimentación y el agua cambian el peso durante el día. Medir en varios momentos permite considerar el mayor peso de transporte; repetir solo la medición matinal o mejorar la precisión no capta esa variación.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4fda4b9e-6c5e-4e51-97f2-89c25d14e1a9', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  '8b5791a9-06c5-4700-869c-624a8f473161', 'Interpretación de datos',
  '¿Qué diagrama representa correctamente ambas modalidades?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q47-a.webp" alt="Ambas rutas comienzan tomando alimentos; una pasa por pesaje y no se añade servicio." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q47-b.webp" alt="Autoservicio: tomar, pesar, consumir y pagar. A la carta: ordenar, consumir, agregar 10 % y pagar." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q47-c.webp" alt="Ambas rutas toman alimentos y el cargo de servicio está unido al pago de otra manera." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q47-d.webp" alt="Ambas rutas convergen antes de agregar el 10 %." loading="lazy"></figure>'],
  'Sigue por separado cada tipo de línea de principio a fin.', 'publicada', 'modelo', '895a7d9492979275af8862972e82027d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4fda4b9e-6c5e-4e51-97f2-89c25d14e1a9', 1, 'El autoservicio debe pasar por pesaje y evitar el recargo. La carta debe empezar ordenando y agregar el 10 % después de consumir. Solo un esquema mantiene las dos condiciones a la vez.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '9d90fe3d-2ce6-497f-8ba1-2bba5e28b5b4', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'tablas-y-probabilidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '86fe941d-1646-4808-9dde-4d309dd98362', 'Tablas y probabilidad',
  '¿Es verdadera la afirmación?',
  array['Sí, porque hay dos formas de obtener once y una sola de obtener cada par.', 'Sí, porque los números diferentes siempre son más probables que los iguales.', 'No, porque cualquier evento tiene la misma probabilidad.', 'No, porque hay dos formas de sumar once y más formas de obtener un par.'],
  'Cuenta resultados elementales, distinguiendo los dos dados.', 'publicada', 'modelo', 'edcf29568511c8244f69f0bc29aade51', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9d90fe3d-2ce6-497f-8ba1-2bba5e28b5b4', 3, 'Once se obtiene con (5,6) y (6,5): 2 resultados. Hay seis pares, desde (1,1) hasta (6,6). Entre 36 resultados equiprobables, 2/36 es menor que 6/36.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
