insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('8342d921-9f3d-4ee8-b6d5-3c3f4efff053', 3, 'Ya se conocen e = 1, m = 5 y s = 14. Solo falta el factor k de la aerolínea para evaluar la fórmula.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
