insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dfadef79-70f4-46f6-9a84-3c052b750e9d', 1, 'Cada mes ahorra 900.000×0,03 = 27.000. En diez meses acumula 27.000×10 = 270.000 pesos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '271fa68b-1026-4d37-b0b4-bd756b7f301a', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'ecuaciones-en-contexto'),
  (select id from public.lotes where codigo = '2026-B'),
  'af152450-0337-4990-aece-bccb61c065ea', 'Ecuaciones en contexto',
  '¿Qué pareja de ecuaciones permite hallar el perímetro, usando cada ecuación por separado?',
  array['1.400 = 5n y 1.400 = n/5.', '1.400 = n + (5 + 2) y 1.400 = (n + 5) + (n + 2).', '1.400 = n(5 + 2) y 1.400 = 5n + 2n.', '1.400/(5×2) = n y (1.400/5)/2 = n.'],
  'Cada vuelta aporta una vez el perímetro completo.', 'publicada', 'modelo', '0cb5051264a1b94301e7f4dd27bd5555', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('271fa68b-1026-4d37-b0b4-bd756b7f301a', 2, 'Las siete vueltas miden 7n = 1.400. La propiedad distributiva permite expresar lo mismo como 5n + 2n. De cualquiera se obtiene n = 200 metros.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '469b5280-15cd-481e-8060-8d8e333fdd4f', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '0155e004-28e3-4904-bfe3-e8b2ff989c0e', 'Áreas y perímetros',
  '¿Qué ocurre con la flecha resultante?',
  array['Se ubica en el segundo cuadrante.', 'Se ubica en el cuarto cuadrante.', 'Apunta hacia el oriente.', 'Apunta hacia el occidente.'],
  'Aplica las transformaciones en el orden indicado.', 'publicada', 'modelo', '12b0bb474f21460b62bcfd6eebcba85e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('469b5280-15cd-481e-8060-8d8e333fdd4f', 1, 'La reflexión lleva (x,y) a (−x,y). La rotación posterior lleva ese punto a (x,−y), en el cuarto cuadrante. La flecha termina apuntando al sur.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'c03af004-8fce-4a8a-bec5-17794e0ff584', 'mat',
