  'e3b383cf-55e0-42d2-8c6e-c5682a973d29', 'Funciones y variación',
  '¿Cuál es la altura del esquiador a los 12 segundos?',
  array['4 metros.', '8 metros.', '12 metros.', '16 metros.'],
  'Ubica el tiempo en el eje horizontal y sube hasta la recta.', 'publicada', 'modelo', 'a0985e67784192fec175c464036ce841', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c03af004-8fce-4a8a-bec5-17794e0ff584', 1, 'La altura disminuye 14/28 = 0,5 m por segundo. A los 12 s vale 14 − 0,5×12 = 8 m, igual que la lectura de la gráfica.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '4514b774-e6ec-486a-a33d-063735939203', 'mat',
