  (select id from public.lotes where codigo = '2026-B'),
  '0b8d2006-2ecb-43aa-9ef9-312476a186d4', 'Interpretación de datos',
  '¿Qué gráfica muestra los tiempos de las atracciones a las que puede ingresar?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q54-a.webp" alt="P, Q y T con tiempos 9, 10 y 11 minutos." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q54-b.webp" alt="R y S con tiempos 8 y 15 minutos." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q54-c.webp" alt="P, Q y T con tiempos 10, 11 y 9 minutos." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/bu2-q54-d.webp" alt="R y S con tiempos 15 y 8 minutos." loading="lazy"></figure>'],
  'Filtra primero por estatura y conserva después el tiempo asociado a cada atracción.', 'publicada', 'modelo', 'e0fdb19a33eea266a1fe79fe1bdf501e', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4514b774-e6ec-486a-a33d-063735939203', 2, 'Su estatura supera los mínimos de P, Q y T. Los tiempos correspondientes son 10, 11 y 9 minutos; R y S exigen más de 140 cm.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
