insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3274a0e5-b227-433b-8325-ac18cc0c99ee', 2, 'Las posiciones pueden llenarse de n(n − 1)(n − 2)(n − 3) formas. Para el menor caso permitido, n = 5, ya hay 120, y el resultado aumenta al tener más trofeos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
