insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4b0f4fe9-f343-421c-a6b2-181e8b48f0c4', 3, 'La fachada mide 10×15 = 150 m². Se restan diez ventanas de 1 m² y una puerta de 2 m²: 150 − 10 − 2 = 138 m².');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
