insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('48e1b2ac-a9a0-4021-b383-e376dcb0d889', 1, 'Una vez seleccionado el primer costo de la lista ordenada, la opción de menor precio ya quedó identificada. Descartar el resto no cambia la decisión.');

